"""Validate the exact R5 extension witness CSV generated by VERIFY_FIRST_DROP.cpp.
Usage: python3 VALIDATE_FIRST_DROP.py witness.csv
All evidence is finite-field/integer; the two infinite zero theorems are proven
in RESEARCH.md and are not inferred from finite-field nonzero failures.
"""
import csv
import math
import sys
from collections import Counter

ORDERS = (32,54,27,25,49,11,13,17,19,23,29,62,37,41,43,47,59,61,73)
MAIN = set(ORDERS) - {27}
LAM = 814202665467037976682352800

def prime_factors(n):
    factors=set()
    for p in range(2, math.isqrt(n)+1):
        while n%p==0:
            factors.add(p)
            n//=p
    if n>1: factors.add(n)
    return factors

def prime(n):
    return n>1 and not any(n%p==0 for p in range(2,math.isqrt(n)+1))

def audit(path):
    with open(path, newline="", encoding="utf-8") as f:
        data=list(csv.DictReader(f))
    assert len(data)==73*len(ORDERS), len(data)
    by={}
    misses=[]
    for row in data:
        m,d,nd,p,z,j,val,cov=(int(row[k]) for k in
             ('m','d','nd','prime','root','first_nonzero_jet','jet_residue','root_coverage'))
        assert (m,d) not in by and 1<=m<=73 and d in MAIN|{27}
        assert prime(p) and (p-1)%d==0
        assert pow(z,d,p)==1 and all(pow(z,d//v,p)!=1 for v in prime_factors(d))
        assert nd==sum(a%d==0 for a in range(214,315))
        if j>=0:
            assert 0<=j<=min(2,nd-2) and 1<=val<p and cov in (1,2)
        else:
            assert val==0 and cov==0
            misses.append((m,d))
        by[m,d]=row
    expected=[(m,54) for m in range(38,55)]+[(m,73) for m in range(69,74)]
    assert misses==expected, (misses,expected)
    for m in range(1,74):
        required=MAIN.copy()
        if 38<=m<=54:
            required.remove(54)
            required.add(27)
        if m>=69:
            required.remove(73)
        assert all(int(by[m,d]["first_nonzero_jet"])>=0 for d in required)
        exact_lcm=math.lcm(*required)
        assert exact_lcm==LAM//(73 if m>=69 else 1), (m,exact_lcm)
    assert math.lcm(*MAIN)==LAM
    assert math.lcm(*(d for d in MAIN if d!=73))==LAM//73
    assert {d for d in range(1,315) if
        sum(a%d==0 for a in range(214,315))>=2 and d%73==0}=={73}
    baseline=[by[m,d] for m in range(1,31) for d in MAIN]
    assert Counter(int(row['first_nonzero_jet']) for row in baseline)==Counter({0:507,1:32,2:1})
    assert (int(by[20,11]['first_nonzero_jet']),int(by[20,11]['jet_residue']))==(2,11)
    print("PASS: 1387 finite-field records; only 17 d54 and 5 d73 root-cancellations")
    print("PASS: 1<=m<=68 period Lambda; 69<=m<=73 period Lambda/73")
    print("PASS: baseline 540 Hasse jets independently match prior R5 frontier")
if __name__=="__main__":
    audit(sys.argv[1])
